#!/usr/bin/env python3
import re
from typing import Any

def hook_validate_entity(entity: dict[str, Any], context: dict[str, Any]) -> list[dict[str, Any]]:
    diagnostics = []
    name = entity.get("name", "")
    content = entity.get("content", "")
    path = entity.get("path", "")

    is_magic = "Magic" in path or "Spell" in path or "Arcane" in path or "Power" in path or "magic" in name.lower()
    if not is_magic and not re.search(r"\b(spell|mana|aether|arcane|sorcery|enchantment|incantation)\b", content, re.IGNORECASE):
        return diagnostics

    has_cost = bool(re.search(r"(cost|limitation|drawback|price|exhaustion|toll|reagent|cooldown|consequence|weakness)", content, re.IGNORECASE))
    if not has_cost:
        diagnostics.append({
            "severity": "warning",
            "message": f"Arcane entity '{name}' describes magical mechanics but defines no explicit Cost, Limitation, or Drawback (Sanderson's Second Law).",
            "target": name,
            "details": {"rule": "sandersons_second_law"},
        })

    has_source = bool(re.search(r"(source|origin|conduit|focus|catalyst|reservoir|ambient|leylines|mana|aether)", content, re.IGNORECASE))
    if not has_source:
        diagnostics.append({
            "severity": "info",
            "message": f"Arcane entity '{name}' does not explicitly define its energy source or catalytic mechanism.",
            "target": name,
        })

    return diagnostics

def hook_validate_manuscript(manuscript: dict[str, Any], context: dict[str, Any]) -> list[dict[str, Any]]:
    diagnostics = []
    chapters = manuscript.get("chapters", [])

    for ch in chapters:
        content = ch.get("content", "")
        title = ch.get("title", "")
        if re.search(r"\b(suddenly\s+discovered\s+a\s+new\s+power|miraculously\s+unlocked|burst\s+of\s+unlimited\s+power)\b", content, re.IGNORECASE):
            diagnostics.append({
                "severity": "warning",
                "message": f"Chapter '{title}' contains phrasing indicative of unheralded magical escalation ('burst of unlimited power'). Ensure foreshadowing exists.",
                "target": title,
            })

    return diagnostics

#!/usr/bin/env python3
import difflib
import re
from typing import Any

VOWELS = set("aeiouyAEIOUY")

def consonant_skeleton(name: str) -> str:
    clean = re.sub(r"[^a-zA-Z]", "", name).lower()
    return "".join(c for c in clean if c not in VOWELS)

def hook_validate_entity(entity: dict[str, Any], context: dict[str, Any]) -> list[dict[str, Any]]:
    diagnostics = []
    name = entity.get("name", "").strip()
    if not name:
        return diagnostics

    if re.search(r"[bcdfghjklmnpqrstvwxzBCDFGHJKLMNPQRSTVWXZ]{5,}", name):
        diagnostics.append({
            "severity": "warning",
            "message": f"Entity name '{name}' contains a dense consonant cluster (5+ consonants) which may impede reader pronunciation.",
            "target": name,
        })

    if name.count("'") > 1 or name.count("`") > 1:
        diagnostics.append({
            "severity": "info",
            "message": f"Entity name '{name}' uses multiple apostrophes/glottal stops.",
            "target": name,
        })

    known_names = context.get("known_names", [])
    if isinstance(known_names, list):
        for other in known_names:
            if other and other != name:
                ratio = difflib.SequenceMatcher(None, name.lower(), other.lower()).ratio()
                if ratio >= 0.85 and abs(len(name) - len(other)) <= 2:
                    diagnostics.append({
                        "severity": "warning",
                        "message": f"Name '{name}' is phonetically/orthographically very close to '{other}' ({int(ratio*100)}% match). Potential reader confusion.",
                        "target": name,
                        "details": {"similar_to": other, "similarity": ratio},
                    })
                elif consonant_skeleton(name) == consonant_skeleton(other) and len(name) > 3:
                    diagnostics.append({
                        "severity": "info",
                        "message": f"Name '{name}' shares identical consonant skeleton ('{consonant_skeleton(name)}') with '{other}'.",
                        "target": name,
                    })

    return diagnostics

def hook_custom_metric(text: str, context: dict[str, Any]) -> dict[str, Any]:
    words = re.findall(r"\b[A-Z][a-z]+\b", text)
    unique_capitalized = set(words)
    return {
        "named_entity_count": len(words),
        "unique_proper_nouns": len(unique_capitalized),
        "proper_noun_density_pct": round(len(words) / max(1, len(text.split())) * 100, 2),
    }
